int main(){try{using T=ks::NativeMonoArpBootstrapService;using K=T::Kind;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;
for(auto kind:{K::Init,K::Reset,K::Output})for(unsigned seed=0;seed<256;++seed)for(unsigned width=1;width<=4;++width){std::fill(m.begin(),m.end(),uint8_t(0));const unsigned rec=seed&1?0x160d3:0x160d2,stream=(seed&8)?0:(seed&2)?0x81a000+0x1000*(seed%16)+(seed&1):(seed&4)?0x87fffc:0x19001;const auto wide=[&](unsigned a,uint32_t v){for(unsigned i=0;i<4;++i)m[a+i]=uint8_t(v>>(24-8*i));};const auto get=[&](unsigned a){uint32_t v=0;for(unsigned i=0;i<4;++i)v=(v<<8)|m[a+i];return v;};wide(rec+48,stream);wide(rec+56,0x11223344);wide(rec+60,0x81234567);m[rec+318]=uint8_t(seed);wide(0x11a7a+((seed<<2)&255),stream);m[0x17526]=uint8_t(seed%5);m[0x167ba]=uint8_t(seed%3);m[0x167d3]=uint8_t(seed);m[0x159f2]=m[0x159f3]=255;for(unsigned i=0;i<32;++i)m[0x1532e + i]=uint8_t(i*17);for(unsigned i=0;i<width;++i)m[stream+i]=uint8_t((seed&127)|(i+1<width?128:0));int previous=-1;unsigned local=0;tracking=true;{T s(kind,{rec,0xffa19801});while(!s.complete()){struct Unknown{};check(!s.task<Unknown>(),"Unknown task query");const auto cost=s.nextClocks(previous);check(cost,"Bootstrap stalled");std::array<unsigned char,sizeof(T)>before{};std::memcpy(before.data(),&s,sizeof(T));unsigned callbacks=0;check(!s.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},previous)&&!callbacks&&!std::memcmp(before.data(),&s,sizeof(T)),"Bootstrap budget mutation");++rejects;check(s.advanceBefore(cost,[&](uint32_t at,unsigned dt){check(at<m.size()&&dt&&dt<=cost,"Bootstrap read bound");++reads;return m[at];},[&](uint32_t at,uint8_t v,unsigned dt){check(at<m.size()&&dt&&dt<=cost&&!(at>=0xfff000&&at<0xfffc00),"Bootstrap write bound");++writes;m[at]=v;previous=at<0x400000?int(at):-1;},previous)==cost,"Bootstrap phase admission");if(s.effect().write)previous=-1;check(++local<1024,"Bootstrap noncompletion");++phases;}
check(s.summary().selected==seed%5&&s.summary().enabled==seed,"Bootstrap live global observations");if(kind!=K::Output){uint32_t delta=0;for(unsigned i=0;i<width;++i)delta=(delta<<7)|(seed&127);delta<<=12;check(s.summary().delta==delta&&get(rec+56)==uint32_t(0x81234567+delta)&&get(rec+52)==stream+width,"Bootstrap independent VLQ/deadline/cursor oracle");}else check(get(rec+56)==0x11223344,"Output touched deadline");struct A{std::array<uint32_t,7>values{};uint8_t flags=0xa5;}a;projectNativeMonoArpBootstrap(a,s);check(a.values[0]==rec&&a.values[4]==0xffa19801,"Bootstrap handle preservation");components|=s.components();}tracking=false;++graphs;}
check(T::span(0,4,false)&&!T::span(0,1,true)&&!T::span(4,1,false),"Header readonly bounded VLQ span");check(T::span(0x800000,4,false)&&T::span(0x87fffc,4,false)&&!T::span(0x800000,1,true)&&!T::span(0x87fffc,1,true)&&!T::span(0x880000,1,false),"Flash readonly physical span boundary");check(components==31&&!allocations,"Bootstrap pure coverage/allocations");std::cout<<"PASS Pure NativeMonoArpBootstrap graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
